import { useEffect, useState } from "react";

import { eseHelpApi } from "../../api/client";
import type { EseHelpResponse } from "../../api/types";

/**
 * In-app reference for the `ese` Python bridge: live project paths (exactly
 * what the kernel sees) + the API generated by the backend from the module's
 * own docstrings/signatures — documentation cannot drift from the code.
 */
export function EseHelpDialog({ projectId, onClose }: { projectId: string; onClose: () => void }) {
  const [data, setData] = useState<EseHelpResponse | null>(null);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    let cancelled = false;
    eseHelpApi
      .get(projectId)
      .then((result) => {
        if (!cancelled) setData(result);
      })
      .catch((err: unknown) => {
        if (!cancelled) setError(err instanceof Error ? err.message : String(err));
      });
    return () => {
      cancelled = true;
    };
  }, [projectId]);

  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      if (e.key === "Escape") onClose();
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [onClose]);

  const functions = (data?.api ?? []).filter((e) => e.owner === null);
  const project_methods = (data?.api ?? []).filter((e) => e.owner === "ProjectHandle");
  const space_methods = (data?.api ?? []).filter((e) => e.owner === "SpaceHandle");

  return (
    <div className="modal-backdrop" role="presentation" onClick={onClose}>
      <div
        className="modal ese-help"
        role="dialog"
        aria-modal="true"
        aria-labelledby="ese-help-title"
        onClick={(e) => e.stopPropagation()}
      >
        <h3 id="ese-help-title" className="modal__title">
          Справка: доступ к данным проекта из Python (<span className="mono">ese</span>)
        </h3>

        {error && <p className="research-dialog__error">{error}</p>}
        {!data && !error && <p className="empty-hint">Загрузка справки…</p>}

        {data && (
          <div className="ese-help__body">
            <section>
              <h4>Пути текущего проекта (вид ядра)</h4>
              <table className="ese-help__paths mono">
                <tbody>
                  <tr>
                    <td>проект</td>
                    <td>
                      {data.context.project_name} (<span title="ESE_PROJECT_ID">{data.context.project_id}</span>)
                    </td>
                  </tr>
                  <tr>
                    <td>cwd ядра / workspace</td>
                    <td>{data.context.workspace_dir}</td>
                  </tr>
                  <tr>
                    <td>notebooks/</td>
                    <td>{data.context.notebooks_dir}</td>
                  </tr>
                  <tr>
                    <td>notes/</td>
                    <td>{data.context.notes_dir}</td>
                  </tr>
                  <tr>
                    <td>results/</td>
                    <td>{data.context.results_dir}</td>
                  </tr>
                  <tr>
                    <td>exports/</td>
                    <td>{data.context.exports_dir}</td>
                  </tr>
                  <tr>
                    <td>project_dir</td>
                    <td>{data.context.project_dir}</td>
                  </tr>
                  <tr>
                    <td>data_dir</td>
                    <td>{data.context.data_dir}</td>
                  </tr>
                  <tr>
                    <td>корни корпуса</td>
                    <td>{data.context.roots.join("; ") || "—"}</td>
                  </tr>
                </tbody>
              </table>
            </section>

            <section>
              <h4>Быстрый старт</h4>
              <pre className="ese-help__quickstart mono">{data.quickstart}</pre>
            </section>

            <section>
              <h4>
                <span className="mono">ese.project</span> — функции модуля
              </h4>
              <ApiList entries={functions} />
            </section>

            <section>
              <h4>
                <span className="mono">ProjectHandle</span> — проект
              </h4>
              <ApiList entries={project_methods} />
            </section>

            <section>
              <h4>
                <span className="mono">SpaceHandle</span> — векторное пространство
              </h4>
              <ApiList entries={space_methods} />
            </section>

            <p className="ese-help__note">
              Справка сгенерирована из самого модуля <span className="mono">ese.project</span>{" "}
              (docstrings и сигнатуры) — она всегда соответствует коду. Всё чтение; основное
              хранилище проекта открывается read-only. Результаты экспериментов сохраняйте в{" "}
              <span className="mono">results_dir</span>.
            </p>
          </div>
        )}

        <div className="modal__actions">
          <button type="button" className="btn btn--small" onClick={onClose}>
            Закрыть
          </button>
        </div>
      </div>
    </div>
  );
}

function ApiList({ entries }: { entries: EseHelpResponse["api"] }) {
  if (entries.length === 0) return <p className="empty-hint">—</p>;
  return (
    <dl className="ese-help__api">
      {entries.map((entry) => (
        <div className="ese-help__api-entry" key={`${entry.owner ?? ""}.${entry.name}`}>
          <dt className="mono">
            {entry.signature}
            {entry.kind === "property" && <span className="ese-help__kind">property</span>}
          </dt>
          <dd>{entry.doc || "—"}</dd>
        </div>
      ))}
    </dl>
  );
}
